select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"id":987111004},"seq":1,"relation":"works","after_row":{"id":987111004,"title":"Candide","cover_id":null,"author_id":987311002,"work_type":null,"source_type":"open_library","open_library_id":"OL100672W","first_publish_year":1759,"native_identity_key":"nlscale:fixture012:334"},"before_row":{"id":987111004,"title":"Candide","cover_id":null,"author_id":987311002,"work_type":null,"source_type":"open_library","open_library_id":"OL100672W","first_publish_year":1746,"native_identity_key":"nlscale:fixture012:334"}},{"key":{"open_library_edition_id":"OL24328781M"},"seq":2,"relation":"editions","after_row":{"id":987211007,"title":"Candide, of Het optimisme","isbn_10":null,"isbn_13":"9789029554343","work_id":987111004,"cover_id":null,"language":"dut","publisher":"De Arbeiderpers","publish_date":null,"open_library_edition_id":"OL24328781M"},"before_row":null},{"key":{"work_id":987111004,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"Candide groeit op met de overtuiging dat alles uiteindelijk zo goed mogelijk geregeld is. Wanneer zijn liefde voor de dochter van een baron wordt ontdekt, moet hij de beschermde omgeving verlaten. Tijdens reizen door verschillende werelddelen krijgt hij vervolgens met geweld, rampen en willekeur te maken. Zijn ervaringen botsen steeds opnieuw met de geruststellende lessen van zijn leermeester Pangloss. Voltaire gebruikt die tegenstelling om vastgeroeste zekerheden en het gemak van theoretisch optimisme te bevragen.","work_id":987111004,"evidence":[{"note":"Candide ou L’optimisme1759, exact Dutch hardcover. KB explicitly explains shortened front title Candide. BnF contemporary1759edition and historical chronology corroborate1759; current1746does not belong to Candide. Canonical original Work is unchanged.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p03620532X"],"reference":"work:334","checked_at