plete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6666749-L.jpg?default=false","edition_id":987211011,"bound_title":"De koopman van Venetië","reviewed_at":"2026-11-02T19:50:00+00:00","bound_isbn13":"9789035108318","evidence_url":"https://data.bibliotheken.nl/id/nbt/p055231942","review_batch":"nl-scale-20261102-012","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/6666749-M.jpg?default=false","bound_author_id":987311001},"before_row":null},{"key":{"id":987111006},"seq":18,"relation":"works","after_row":{"id":987111006,"title":"Eline Vere","cover_id":null,"author_id":978300007,"work_type":null,"source_type":"open_library","open_library_id":"OL1456910W","first_publish_year":1889,"native_identity_key":"nlscale:fixture012:1193"},"before_row":{"id":987111006,"title":"Eline Vere","cover_id":null,"author_id":978300007,"work_type":null,"source_type":"open_library","open_library_id":"OL1456910W","first_publish_year":1892,"native_identity_key":"nlscale:fixture012:1193"}},{"key":{"open_library_edition_id":"OL24651397M"},"seq":19,"relation":"editions","after_row":{"id":987211012,"title":"Eline Vere","isbn_10":null,"isbn_13":"9789020425895","work_id":987111006,"cover_id":null,"language":"dut","publisher":"Veen","publish_date":null,"open_library_edition_id":"OL24651397M"},"before_row":null},{"key":{"work_id":987111006,"language":"nl"},"seq":20,"relation":"catalog_work_descriptions","after_row":{"text":"Eline Vere woont bij haar zus Betsy en haar zwager in Den Haag. In hun welgestelde omgeving volgen visites, muziekavonden en huwelijksplannen elkaar op. Eline verlangt naar een leven dat overeenkomt met haar romantische verwachtingen, maar twijfelt voortdurend aan zichzelf en aan de mensen om haar heen. Haar neef Vincent beïnvloedt haar met zijn opvattingen over het noodlot. Couperus volgt hoe haar innerlijke onrust botst met het sociale leven waarin zij een plaats probeert te vinden.","work_id":987111006,"evidence":[{"note":"Couperus ElineVere: same novel, distinct1888serial/1889book dates retained without new year correction. Hardback is an explicit print synonym. First book edition1889, preceding newspaper serial1888 and later third printing1892 explicitly distinguished. Correct current1892to first book1889. Exact new Veen print is not guessed to be the legacy ISBN-less edition.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p041486617","http://data.bibliotheken.nl/id/nbt/p411877461","http://data.bibliotheken.nl/id/nbt/p371669065"],"reference":"work:1193","checked_at":"2026-11-02T19:50:00.000Z","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://www.dbnl.org/tekst/anbe001lexi01_01/lvlw00134.php?q=gemoderniseerd","https://www.dbnl.org/titels/titel.php?id=coup002elin01","https://www.dbnl.org/tekst/coup002elin01_01/colofon.php","https://www.bibliotheek.nl/catalogus/titel.436207516.html/eline-vere/","https://openlibrary.org/works/OL1456910W","https://data.bibliotheken.nl/id/nbt/p041486617","https://data.bibliotheken.nl/id/nbt/p411877461","https://data.bibliotheken.nl/id/nbt/p371669065"]},{"type":"cover_front_review","sha256":"8a3aa08fb4d75f4d69a3ca1af57ca83db0d5dfce09f092ca8a96e32e5e3f919a","cover_id":6759584,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-001.jpg. Louis Couperus; Eline Vere; Veen uitgevers. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.dbnl.org/tekst/anbe001lexi01_01/lvlw00134.php?q=gemoderniseerd","reviewed_at":"2026-11-02T19:50:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch